'use strict';
const generatedInvites=new Map();
async function invitationAdmin(action,g){if(!await admin())throw Error('Akses pengelola diperlukan.');await syncNow();const r=await TemuStore.read();if(r.outbox.length||r.conflicts.some(x=>!x.resolved))throw Error('Selesaikan sinkronisasi dan konflik sebelum membuat akses undangan.');if(!r.config.enabled||!r.config.token)throw Error('Hubungkan server terlebih dahulu.');const response=await fetch('/api/invite/admin/'+action,{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+r.config.token,'X-Temu-Invite':'1'},body:JSON.stringify({event:r.state.event.id,guest:g.id}),cache:'no-store',signal:AbortSignal.timeout(15000)});const data=await response.json();if(!response.ok)throw Error(data.error||'Akses undangan tidak dapat disiapkan.');return data;}
function invitationOrigin(){const configured=db.event.wedding?.publicOrigin;return configured||location.origin;}
function showGuestInvitation(g){
 const key=db.event.id+':'+g.id,existing=generatedInvites.get(key);modal('Undangan pribadi · '+g.name,`<p>Undangan hanya ditampilkan setelah tautan pribadi dan kode akses cocok dengan tamu aktif.</p><div class="actions"><button id="preview-invitation">Pratinjau undangan</button><button id="issue-invitation" class="primary">Buat / ganti akses</button><button id="revoke-invitation">Cabut akses</button></div><p class="hint">Mengganti akses membatalkan tautan dan sesi lama. Kode akses disampaikan secara terpisah kepada nomor tamu yang telah Anda verifikasi.</p><div id="issued-invitation"></div>`);
 const renderAccess=access=>{const url=new URL('/invite',invitationOrigin());url.hash=access.link;$('#issued-invitation').innerHTML=`<label>Tautan pribadi<input id="private-invite-link" readonly value="${esc(url.href)}"></label><label>Kode akses (kirim terpisah)<input id="private-invite-code" readonly value="${esc(access.code)}"></label><p class="hint">Simpan kode ini sebelum menutup aplikasi. Server hanya menyimpan hash kode. Jangan sertakan kode pada pesan berisi tautan.</p><div class="actions"><button id="copy-private-link">Salin tautan</button><button id="copy-private-code">Salin kode</button><button id="share-private-invite" class="primary">QR + tautan via WhatsApp</button></div><p class="hint">${url.hostname==='localhost'||url.hostname==='127.0.0.1'?'Alamat masih lokal dan tidak dapat dibuka di ponsel tamu. Siapkan hosting HTTPS lalu isi Alamat undangan publik di Pengaturan.':'Penerima tetap perlu memasukkan kode akses yang Anda berikan secara terpisah.'}</p>`;
 for(const [button,field] of [['copy-private-link','private-invite-link'],['copy-private-code','private-invite-code']])$('#'+button).onclick=async()=>{try{await navigator.clipboard.writeText($('#'+field).value);toast('Disalin.');}catch{$('#'+field).select();toast('Pilih dan salin secara manual.');}};
 $('#share-private-invite').onclick=()=>{if(url.hostname==='localhost'||url.hostname==='127.0.0.1')return toast('Atur alamat publik HTTPS sebelum membagikan tautan kepada tamu.');showWhatsApp(g,url.href);};
 };
 if(existing)renderAccess(existing);
 $('#issue-invitation').onclick=async()=>{if(!confirm('Buat akses baru untuk tamu ini? Tautan dan sesi undangan lama akan dinonaktifkan.'))return;try{const access=await invitationAdmin('issue',g);generatedInvites.set(key,access);renderAccess(access);}catch(e){toast(e.message);}};
 $('#revoke-invitation').onclick=async()=>{if(!confirm('Cabut akses halaman undangan tamu ini? QR check-in tetap berlaku sampai undangan dinonaktifkan di Daftar tamu.'))return;try{await invitationAdmin('revoke',g);generatedInvites.delete(key);$('#issued-invitation').replaceChildren();toast('Akses halaman undangan dicabut.');}catch(e){toast(e.message);}};
 $('#preview-invitation').onclick=async()=>{try{await invitationAdmin('preview',g);const a=document.createElement('a');a.href='/invite';a.target='_blank';a.rel='noopener';a.textContent='Buka pratinjau undangan';a.className='button';$('#issued-invitation').replaceChildren(a);a.click();}catch(e){toast(e.message);}};
}
